CREATE TEMP TABLE editorial_cold_patch ON COMMIT DROP AS SELECT value p FROM jsonb_array_elements($cold_patch$[{"id":"b5bcb5a0-0726-44e1-ba3a-2d3f9a867bcb","slug":"prepmeal-25-16-chickpea-salad","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"33903a60b76678975f4c91a1c4185b1d9ff07da186140556b69bb7a6d4cae5d9","cooking_tips":["使用可即食的熟鷹嘴豆並瀝水；乾鷹嘴豆不能直接拌入當作同一材料。","雞肉、吞拿魚與Feta屬選配，按實際選用加入；加雞肉時須確認已熟，拌好保持冷藏。"],"pairing_suggestions":["可配「孜然香辣烤豆腐」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}],"served_cold":true},"old":{"version":1,"references":[{"url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html","title":"食物安全中心：烹煮及翻熱"}],"reviewed_on":"2026-11-13","cooking_tips":["使用可即食的熟鷹嘴豆並瀝水；乾鷹嘴豆不能直接拌入當作同一材料。","雞肉、吞拿魚與Feta屬選配，按實際選用加入；加雞肉時須確認已熟，拌好保持冷藏。"],"review_method":"desk_review_not_test_cooked","source_fingerprint":"33903a60b76678975f4c91a1c4185b1d9ff07da186140556b69bb7a6d4cae5d9","pairing_suggestions":["可配「孜然香辣烤豆腐」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"]}},{"id":"a2eee8c2-0e5f-48fb-bd2c-fc098b7b74ff","slug":"prepmeal-25-19-yum-woon-sen","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"3ee28c2f32daeb8e773fd8b775a0ad3422a0e414e3dca5e3fb06292fda36e026","cooking_tips":["粉絲、蝦與肉碎要先各自煮熟，再與已洗淨的蔬菜拌合，不以酸辣汁代替煮熟。","花生最後才拌，熟材料拌好後盡快食用或冷藏，不能因名為沙律就久放室溫。"],"pairing_suggestions":["這道菜已有乾綠豆粉絲，可配「清炒菜心」；其他主食按整餐份量安排。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}],"served_cold":true},"old":{"version":1,"references":[{"url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html","title":"食物安全中心：烹煮及翻熱"}],"reviewed_on":"2026-11-13","cooking_tips":["粉絲、蝦與肉碎要先各自煮熟，再與已洗淨的蔬菜拌合，不以酸辣汁代替煮熟。","花生最後才拌，熟材料拌好後盡快食用或冷藏，不能因名為沙律就久放室溫。"],"review_method":"desk_review_not_test_cooked","source_fingerprint":"3ee28c2f32daeb8e773fd8b775a0ad3422a0e414e3dca5e3fb06292fda36e026","pairing_suggestions":["這道菜已有乾綠豆粉絲，可配「清炒菜心」；其他主食按整餐份量安排。"]}},{"id":"a857763a-b6b6-4df6-9005-81d31a6ea592","slug":"prepmeal-25-14-som-tam","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"1fcfb6f5cbccf78a8b71137e2e4d9bcaa29ff448548d3f2424af4712537eb1ea","cooking_tips":["青木瓜刨絲後才輕壓拌汁，不必把瓜絲壓至爛；棕櫚糖先在汁中調開。","豆角須先用沸水徹底煮熟、降溫再拌，不能把醬汁的酸味當成煮熟處理。"],"pairing_suggestions":["可配「豆腐雞蛋白菜卷」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[{"title":"食物安全中心：未煮熟豆類中的天然毒素","url":"https://www.cfs.gov.hk/tc_chi/multimedia/multimedia_pub/multimedia_pub_fsf_139_04.html"}],"served_cold":true},"old":{"version":1,"references":[{"url":"https://www.cfs.gov.hk/tc_chi/multimedia/multimedia_pub/multimedia_pub_fsf_139_04.html","title":"食物安全中心：未煮熟豆類中的天然毒素"}],"reviewed_on":"2026-11-13","cooking_tips":["青木瓜刨絲後才輕壓拌汁，不必把瓜絲壓至爛；棕櫚糖先在汁中調開。","如用四季豆或來源未明的豆角，須先煮熟降溫再拌，不能把醬汁的酸味當成煮熟處理。"],"review_method":"desk_review_not_test_cooked","source_fingerprint":"975eeb2ab4d975b8514bb53fad086b11a8eff92a79091463523532bec684a9c7","pairing_suggestions":["可配「豆腐雞蛋白菜卷」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"]}},{"id":"d017d3a4-f0bc-4670-82dd-76becb24bc91","slug":"prepmeal-25-13-larb","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"83b0ec238fd6186f2d6320564f4d721829a87f2f39ab36a5e5d30ee9e3f504c8","cooking_tips":["生米先乾烘、放涼再磨粉，不能把未處理的生米粒直接拌入。","肉碎先煮至全熟才離火拌汁，香草稍降溫後加入，酸汁不是生肉的殺菌步驟。"],"pairing_suggestions":["這道菜已有白米，可配「蒜蓉生菜」；其他主食按整餐份量安排。"],"references":[],"served_cold":true},"old":{"version":1,"references":[],"reviewed_on":"2026-11-13","cooking_tips":["生米先乾烘、放涼再磨粉，不能把未處理的生米粒直接拌入。","肉碎先煮至全熟才離火拌汁，香草稍降溫後加入，酸汁不是生肉的殺菌步驟。"],"review_method":"desk_review_not_test_cooked","source_fingerprint":"83b0ec238fd6186f2d6320564f4d721829a87f2f39ab36a5e5d30ee9e3f504c8","pairing_suggestions":["這道菜已有白米，可配「蒜蓉生菜」；其他主食按整餐份量安排。"]}},{"id":"9815a71b-e33e-441d-a524-78eb13990ead","slug":"cold-tossed-baby-napa-cabbage","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"3d20a3f91868088f044410a646f42f9b6159551bbfe0ffc1fdd671b680c90b64","cooking_tips":["娃娃菜汆熟後充分瀝水，醬汁才不會被菜水沖淡。","如過冷水，使用可飲用冷水及乾淨器具；拌好即食，不另加未列出的辣油。"],"pairing_suggestions":["可配「豆腐雞蛋白菜卷」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[],"served_cold":true},"old":{"version":1,"references":[],"reviewed_on":"2026-11-13","cooking_tips":["娃娃菜汆熟後充分瀝水，醬汁才不會被菜水沖淡。","如過冷水，使用可飲用冷水及乾淨器具；拌好即食，不另加未列出的辣油。"],"review_method":"desk_review_not_test_cooked","source_fingerprint":"3d20a3f91868088f044410a646f42f9b6159551bbfe0ffc1fdd671b680c90b64","pairing_suggestions":["可配「豆腐雞蛋白菜卷」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"]}},{"id":"b3d03435-db93-4196-bbdb-b93b73c14587","slug":"cold-black-fungus-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"eda6dc52b9bdbe4407dd3fd0d57527dd503ae10013ebf35d2bc6d381849d4996","cooking_tips":["120克指已浸發濕木耳的瀝水重，不能用同重乾木耳代替。","木耳先按包裝煮熟，再用可飲用冷水處理並瀝乾；醬汁以材料表總量為準。"],"pairing_suggestions":["可配「孜然香辣烤豆腐」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[],"served_cold":true},"old":{"version":1,"references":[],"reviewed_on":"2026-11-13","cooking_tips":["120克指已浸發濕木耳的瀝水重，不能用同重乾木耳代替。","木耳先按包裝煮熟，再用可飲用冷水處理並瀝乾；醬汁以材料表總量為準。"],"review_method":"desk_review_not_test_cooked","source_fingerprint":"eda6dc52b9bdbe4407dd3fd0d57527dd503ae10013ebf35d2bc6d381849d4996","pairing_suggestions":["可配「孜然香辣烤豆腐」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"]}},{"id":"a9e4a872-b2b5-43b5-a267-538e9a798b62","slug":"cold-seaweed-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"987f5813f4f1188393aacc2ea10e4f7ac3f57039b61d617981b934721ebb6c4d","cooking_tips":["先確認海帶是已泡發、可烹煮的濕品，按包裝去鹽煮熟，不把汆水留作調味汁。","拌好後即食或盡快冷藏，生抽與醋不因試味而超出材料表總量。"],"pairing_suggestions":["可配「豆腐雞蛋白菜卷」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[{"t