alad","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"5a5ae18df5bc8250980e98cdbb735649ac01b9621c1b173c372f02bced7e391d","cooking_tips":["雞胸先煮熟，再用乾淨砧板切片，不讓生雞器具接觸洗好的即食菜。","沙律菜充分瀝乾，食前才加醬；熟雞稍降溫不代表可把整碗長放室溫。"],"pairing_suggestions":["本餐已包含主食，可配「清炒芥蘭」；飯麵不必重複加一份。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}],"served_cold":true},"old":{"version":1,"references":[{"url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html","title":"食物安全中心：烹煮及翻熱"}],"reviewed_on":"2026-11-13","cooking_tips":["雞胸先煮熟，再用乾淨砧板切片，不讓生雞器具接觸洗好的即食菜。","沙律菜充分瀝乾，食前才加醬；熟雞稍降溫不代表可把整碗長放室溫。"],"review_method":"desk_review_not_test_cooked","source_fingerprint":"5a5ae18df5bc8250980e98cdbb735649ac01b9621c1b173c372f02bced7e391d","pairing_suggestions":["本餐已包含主食，可配「清炒芥蘭」；飯麵不必重複加一份。"]}},{"id":"ddc92d24-dbf7-4b11-8152-9fc0b7f61944","slug":"prepmeal-batch2-15","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"825763cb7b90608d8324a466d62bd6211c6e05b5e8596ab6721aaad03e25f88a","cooking_tips":["芽菜須煮至全熟再用可飲用冷水降溫，短汆時間按份量延長，不保留生硬中心。","瀝乾輕擠才拌麻油與魚露，拌好保持冷藏，不能因名為涼拌便使用生芽菜。"],"pairing_suggestions":["可配「豆腐雞蛋白菜卷」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}],"served_cold":true},"old":{"version":1,"references":[{"url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html","title":"食物安全中心：烹煮及翻熱"}],"reviewed_on":"2026-11-13","cooking_tips":["芽菜須煮至全熟再用可飲用冷水降溫，短汆時間按份量延長，不保留生硬中心。","瀝乾輕擠才拌麻油與魚露，拌好保持冷藏，不能因名為涼拌便使用生芽菜。"],"review_method":"desk_review_not_test_cooked","source_fingerprint":"825763cb7b90608d8324a466d62bd6211c6e05b5e8596ab6721aaad03e25f88a","pairing_suggestions":["可配「豆腐雞蛋白菜卷」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"]}}]$cold_patch$::jsonb);
DO $fix$
DECLARE rec record; n integer;
BEGIN
 PERFORM id FROM public.recipes WHERE id IN(SELECT(p->>'id')::uuid FROM editorial_cold_patch) ORDER BY id FOR UPDATE;
 FOR rec IN SELECT p FROM editorial_cold_patch LOOP
  IF NOT EXISTS(SELECT 1 FROM public.recipes WHERE id=(rec.p->>'id')::uuid AND source_data->'editorial_guidance'=rec.p->'old') THEN RAISE EXCEPTION 'Cold dish precondition changed'; END IF;
 END LOOP;
 UPDATE public.recipe_steps SET text='大碗中把木瓜絲、已煮熟並降溫的豆角、其他材料及醬汁拌勻並輕壓，至木瓜絲稍軟；拌好盡快食用。' WHERE recipe_id='a857763a-b6b6-4df6-9005-81d31a6ea592' AND step_no=4 AND text='大碗中把所有材料拌勻並輕壓，至木瓜絲稍軟；使用已烘花生可免開火。';
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>1 THEN RAISE EXCEPTION 'Salad step precondition changed'; END IF;
 FOR rec IN SELECT p FROM editorial_cold_patch LOOP
  UPDATE public.recipes SET source_data=jsonb_set(source_data,'{editorial_guidance}',rec.p->'guidance',true) WHERE id=(rec.p->>'id')::uuid;
 END LOOP;
END $fix$;
COMMIT;
